1	import java.awt.*;
2	import java.awt.event.*;
3	import javax.swing.*;
4	import java.util.LinkedHashMap;
5	import java.util.Map;
6	import javax.swing.border.EmptyBorder;
7	/**
8	 * A graphical view of the simulation grid.
9	 * The view displays a colored rectangle for each location 
10	 * representing its contents. It uses a default background color.
11	 * Colors for each type of species can be defined using the
12	 * setColor method.
13	 *
14	 * @version 2016.02.29
15	 */
16	public class SimulatorView extends JFrame
17	{
18	    // Colors used for empty locations.
19	    private static final Color EMPTY_COLOR = Color.white;
20	
21	    // Color used for objects that have no defined color.
22	    private static final Color UNKNOWN_COLOR = Color.gray;
23	
24	    private final String STEP_PREFIX = "Step: ";
25	    private final String POPULATION_PREFIX = "Population: ";
26	    private final String WEATHER_PREFIX = "Weather: ";
27	    private final String DAYSTATE_PREFIX = "Light: ";
28	    private JLabel stepLabel, population, infoLabel, dayLabel, weatherLabel;
29	    private JToolBar sideBar;
30	    private FieldView fieldView;
31	    
32	    // A map for storing colors for participants in the simulation
33	    private Map<Class, Color> colors;
34	    // A statistics object computing and storing simulation information
35	    private FieldStats stats;
36	    private Simulator simulator;
37	    
38	    /*///////////////////////////////////////////////////////////////
39	                                CONSTRUCTOR
40	    //////////////////////////////////////////////////////////////*/
41	    
42	    /**
43	     * Create a view of the given width and height.
44	     * 
45	     * @param height The simulation's height.
46	     * @param width  The simulation's width.
47	     */
48	    public SimulatorView(int height, int width, Simulator simulator)
49	    {
50	        // set instance variables
51	        this.simulator = simulator;
52	        stats = new FieldStats();
53	        colors = new LinkedHashMap<>();
54	        setTitle("Fox and Rabbit Simulation");
55	        
56	        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
57	        infoLabel = new JLabel("00 | 00", JLabel.CENTER);
58	        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
59	        // setup dashboard button
60	        JButton dashboardButton = new JButton("Dashboard");
61	        dashboardButton.setMargin(new Insets(4, 4, 4, 4));
62	        dashboardButton.addActionListener(new ActionListener(){
63	                            public void actionPerformed(ActionEvent e) {
64	                            
65	                                simulator.setDashboard(new Dashboard(stats.getCounters(), DiseaseHandler.count));
66	                            }
67	        
68	                        });
69	        sideBar = new JToolBar(JToolBar.VERTICAL);
70	        
71	        dashboardButton.setAlignmentX(CENTER_ALIGNMENT);
72	        //setup sidebar + styling + eventhandler
73	        sideBar.setFloatable(false);
74	        sideBar.setMargin(new Insets(10, 10, 10, 10));
75	        sideBar.setLayout(new BoxLayout(sideBar, BoxLayout.Y_AXIS));
76	        //setup simulate step button + styling + evenhandler
77	        JButton simulateButton = new JButton("Simulate (1)");
78	        simulateButton.addActionListener(new ActionListener(){
79	                            public void actionPerformed(ActionEvent e) {
80	                                
81	                                
82	                                simulator.simulateOneStep();
83	                            }
84	        
85	                        });
86	        simulateButton.setAlignmentX(CENTER_ALIGNMENT);
87	        simulateButton.setMargin(new Insets(4, 4, 4, 4));
88	        
89	        //setup simulate long simulation + eventhandler
90	        JButton simulateLong = new JButton("Simulate(1000)");
91	        simulateLong.addActionListener(new ActionListener(){
92	                public void actionPerformed(ActionEvent e) {
93	                    new Thread(simulator::runLongSimulation).start();
94	                }
95	        });
96	        simulateLong.setAlignmentX(CENTER_ALIGNMENT);
97	        simulateLong.setMargin(new Insets(4, 4, 4, 4));
98	        
99	        setLocation(100, 50);
100	        //Append components to toolbar
101	        sideBar.add(simulateButton);
102	        sideBar.add(Box.createVerticalStrut(8));
103	        sideBar.add(simulateLong);
104	        sideBar.add(Box.createVerticalStrut(8));
105	        sideBar.add(dashboardButton);
106	        // set up labels
107	        dayLabel = new JLabel("");
108	        weatherLabel= new JLabel("");
109	        dayLabel.setAlignmentX(CENTER_ALIGNMENT);
110	        
111	        weatherLabel.setAlignmentX(CENTER_ALIGNMENT);
112	        
113	        dayLabel.setBorder(new EmptyBorder(4,0,4,0));
114	        weatherLabel.setBorder(new EmptyBorder(4,0,4,0));
115	        sideBar.add(dayLabel);
116	        sideBar.add(weatherLabel);
117	        // create grid
118	        fieldView = new FieldView(height, width);
119	        
120	        Container contents = getContentPane();
121	        // append components to main frame
122	        JPanel infoPane = new JPanel(new BorderLayout());
123	            infoPane.add(stepLabel, BorderLayout.WEST);
124	            infoPane.add(infoLabel, BorderLayout.CENTER);
125	        
126	        contents.add(infoPane, BorderLayout.NORTH);
127	        contents.add(fieldView, BorderLayout.CENTER);
128	        contents.add(population, BorderLayout.SOUTH);
129	        contents.add(sideBar, BorderLayout.WEST);
130	        pack();
131	        setVisible(true);
132	    }
133	    
134	    /**
135	     * Define a color to be used for a given class of animal.
136	     * 
137	     * @param animalClass The animal's Class object.
138	     * @param color The color to be used for the given class.
139	     */
140	    public void setColor(Class animalClass, Color color)
141	    {
142	        colors.put(animalClass, color);
143	    }
144	
145	    /**
146	     * Display a short information label at the top of the window.
147	     */
148	    public void setInfoText(String text)
149	    {
150	        infoLabel.setText(text);
151	    }
152	    
153	    /**
154	     * Displays colors associated with the animals in the side bar.
155	     */
156	    public void showColors()
157	    {
158	        for (Class cls : colors.keySet()) {
159	            JLabel tempLabel = new JLabel(cls.getName());
160	            tempLabel.setForeground(colors.get(cls));
161	            tempLabel.setAlignmentX(CENTER_ALIGNMENT);
162	            tempLabel.setBorder(new EmptyBorder(4,0,4,0));
163	            sideBar.add(tempLabel);
164	        }
165	        
166	    }
167	    
168	    /**
169	     * Returns a color to be used for a given class of animal
170	     * 
171	     * @return The color to be used for a given class of animal.
172	     */
173	    private Color getColor(Class animalClass)
174	    {
175	        Color col = colors.get(animalClass);
176	        if(col == null) {
177	            // no color defined for this class
178	            return UNKNOWN_COLOR;
179	        }
180	        else {
181	            return col;
182	        }
183	    }
184	
185	    /**
186	     * Show the current status of the field.
187	     * 
188	     * @param step Which iteration step it is.
189	     * @param field The field whose status is to be displayed.
190	     */
191	    public void showStatus(int step, Field field, SimulatorClock clock, Weather weather)
192	    {
193	        if(!isVisible()) {
194	            setVisible(true);
195	        }
196	            
197	        stepLabel.setText(STEP_PREFIX + step);
198	        infoLabel.setText(clock.getStringTime());
199	        weatherLabel.setText(WEATHER_PREFIX + weather.name().toLowerCase());
200	        dayLabel.setText(DAYSTATE_PREFIX + clock.getDayState().name().toLowerCase());
201	        stats.reset();
202	        
203	        fieldView.preparePaint();
204	
205	        for(int row = 0; row < field.getDepth(); row++) {
206	            for(int col = 0; col < field.getWidth(); col++) {
207	                Object animal = field.getObjectAt(row, col);
208	                //animal takes precendence over plants
209	                if(animal != null) {
210	                    stats.incrementCount(animal.getClass());
211	                    fieldView.drawMark(col, row, getColor(animal.getClass()));
212	                }
213	                else if(field.getPlantAt(row, col) != null) {
214	                    // if the cell is not occupied by an animal, attempt to occupy with plant. 
215	                    Plant plant = field.getPlantAt(row, col);
216	                    stats.incrementCount(plant.getClass());
217	                    fieldView.drawMark(col, row, getColor(plant.getClass()));
218	                }
219	                else {
220	                    fieldView.drawMark(col, row, EMPTY_COLOR);
221	                }
222	            }
223	        }
224	        stats.countFinished();
225	
226	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
227	        fieldView.repaint();
228	    }
229	
230	    /**
231	     * Determine whether the simulation should continue to run.
232	     * @return true If there is more than one species alive.
233	     */
234	    public boolean isViable(Field field)
235	    {
236	        return stats.isViable(field);
237	    }
238	    
239	    /**
240	     * Provide a graphical view of a rectangular field. This is 
241	     * a nested class (a class defined inside a class) which
242	     * defines a custom component for the user interface. This
243	     * component displays the field.
244	     * This is rather advanced GUI stuff - you can ignore this 
245	     * for your project if you like.
246	     */
247	    private class FieldView extends JPanel
248	    {
249	        private final int GRID_VIEW_SCALING_FACTOR = 6;
250	
251	        private int gridWidth, gridHeight;
252	        private int xScale, yScale;
253	        Dimension size;
254	        private Graphics g;
255	        private Image fieldImage;
256	
257	        /**
258	         * Create a new FieldView component.
259	         */
260	        public FieldView(int height, int width)
261	        {
262	            gridHeight = height;
263	            gridWidth = width;
264	            size = new Dimension(0, 0);
265	        }
266	
267	        /**
268	         * Tell the GUI manager how big we would like to be.
269	         */
270	        public Dimension getPreferredSize()
271	        {
272	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
273	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
274	        }
275	
276	        /**
277	         * Prepare for a new round of painting. Since the component
278	         * may be resized, compute the scaling factor again.
279	         */
280	        public void preparePaint()
281	        {
282	            if(! size.equals(getSize())) {  // if the size has changed...
283	                size = getSize();
284	                fieldImage = fieldView.createImage(size.width, size.height);
285	                g = fieldImage.getGraphics();
286	
287	                xScale = size.width / gridWidth;
288	                if(xScale < 1) {
289	                    xScale = GRID_VIEW_SCALING_FACTOR;
290	                }
291	                yScale = size.height / gridHeight;
292	                if(yScale < 1) {
293	                    yScale = GRID_VIEW_SCALING_FACTOR;
294	                }
295	            }
296	        }
297	        
298	        /**
299	         * Paint on grid location on this field in a given color.
300	         */
301	        public void drawMark(int x, int y, Color color)
302	        {
303	            g.setColor(color);
304	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
305	        }
306	
307	        /**
308	         * The field view component needs to be redisplayed. Copy the
309	         * internal image to screen.
310	         */
311	        public void paintComponent(Graphics g)
312	        {
313	            if(fieldImage != null) {
314	                Dimension currentSize = getSize();
315	                if(size.equals(currentSize)) {
316	                    g.drawImage(fieldImage, 0, 0, null);
317	                }
318	                else {
319	                    // Rescale the previous image.
320	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
321	                }
322	            }
323	        }
324	    }
325	}
